local config = {
  ui_story_5023_50230101_1_dialog_content = "Jadi... Anak muda, mungkin Anda harus memikirkannya lagi.",
  ui_story_5023_50230101_2_dialog_content = "Mengapa? Apakah ada yang salah dengan formulir aplikasi saya?",
  ui_story_5023_50230101_3_dialog_content = "Pertama-tama, kami tidak pernah menggunakan formulir aplikasi apa pun.",
  ui_story_5023_50230101_4_dialog_content = "Jika alasan Anda ingin bergabung dengan Rediesel Wrench adalah untuk Azure...",
  ui_story_5023_50230101_5_dialog_content = "Saya menyarankan Anda untuk mencoba keberuntungan Anda di Squirming Sandworm. Dia benar-benar menghabiskan lebih banyak waktu di sana daripada di pangkalan.",
  ui_story_5023_50230101_6_dialog_content = "Hai, Roy. Saya jarang melihat Anda mengobrol dengan orang seperti ini. Memiliki hari yang santai?",
  ui_story_5023_50230101_7_dialog_content = "… Azure!",
  ui_story_5023_50230101_8_dialog_content = "Apa ini?",
  ui_story_5023_50230101_9_dialog_content = "Orang ke-18 bulan ini yang ingin bergabung dengan Rediesel Wrench karena kamu.",
  ui_story_5023_50230101_10_dialog_content = "Apakah kamu tidak ingat saya? Suatu malam Anda masuk ...",
  ui_story_5023_50230101_11_dialog_content = "Anda mengikat saya ke kursi dan mencambuk saya dengan ikat pinggang. Anda bahkan memasang kerah dan rantai pada saya.",
  ui_story_5023_50230101_12_dialog_content = "Anda tidak ingat?",
  ui_story_5023_50230101_13_dialog_content = "Ah... Kau yang dari Blue Lion Guild...",
  ui_story_5023_50230101_14_dialog_content = "Mmm!",
  ui_story_5023_50230101_15_dialog_content = "Heh... betapa kokohnya tubuhmu. Ikat pinggang putus...",
  ui_story_5023_50230101_16_dialog_content = "Siap memberitahuku di mana Blue Lion Guild menyembunyikan kargo kita?",
  ui_story_5023_50230101_17_dialog_content = "... Banteng! Kargo Anda? Anda menjarah kereta kami, kami baru saja mengambil kembali milik kami!",
  ui_story_5023_50230101_18_dialog_content = "Apa milikmu adalah milikku, dan milikku adalah milikku. Kau mengerti?",
  ui_story_5023_50230101_19_dialog_content = "Aku... Aku tidak punya apa-apa untuk diberitahukan padamu. Buat itu cepat.",
  ui_story_5023_50230101_20_dialog_content = "Saya tidak berpikir Anda tahu garis antara keberanian dan kebodohan.",
  ui_story_5023_50230101_21_dialog_content = "Bagus. Mari kita lakukan ini dengan cara yang berbeda.",
  ui_story_5023_50230101_22_dialog_content = "<color=#e8d9bb>Klik</color>",
  ui_story_5023_50230101_23_dialog_content = "Tidak buruk, itu sangat cocok untukmu.",
  ui_story_5023_50230101_24_dialog_content = "A-Apa ini?",
  ui_story_5023_50230101_25_dialog_content = "Seseorang meminta saya untuk membeli kerah dan rantai ini dari Pasar Umbraton untuk mereka.",
  ui_story_5023_50230101_26_dialog_content = "Saya tidak berpikir warna ini cocok dengan imut yang dimaksudkan untuk itu, jadi saya berencana untuk membeli yang lain.",
  ui_story_5023_50230101_27_dialog_content = "Betapa indahnya itu sangat cocok untuk Anda! Kalau tidak, itu akan sia-sia.",
  ui_story_5023_50230101_28_dialog_content = "... Apa yang akan kamu lakukan padaku?",
  ui_story_5023_50230101_29_dialog_content = "Hmm...mari kita lihat. Mengapa saya tidak merantai Anda di belakang mobil saya dan membawa kami berkeliling Umbraton?",
  ui_story_5023_50230101_30_dialog_content = "?!",
  ui_story_5023_50230101_31_dialog_content = "Jika itu tidak cukup menggetarkan bagimu, kurasa aku bisa menyeretmu ke negara tempat Eclipsites berada...",
  ui_story_5023_50230101_32_dialog_content = "<color=#e8d9bb>Kresek…</color>",
  ui_story_5023_50230101_33_dialog_content = "Javier!",
  ui_story_5023_50230101_34_dialog_content = "Tanaman acer? Aku menyuruhmu untuk tetap bersembunyi!",
  ui_story_5023_50230101_35_dialog_content = "Jangan sakiti saudaraku, kumohon! *Menangis*",
  ui_story_5023_50230101_36_dialog_content = "Javier... Tolong! Jangan tinggalkan aku!",
  ui_story_5023_50230101_37_dialog_content = "Suara apa itu?",
  ui_story_5023_50230101_38_dialog_content = "Bukankah kita baru saja mengosongkan gudang? Mungkinkah seseorang mengintai untuk menyelidiki Sight?",
  ui_story_5023_50230101_39_dialog_content = "B-Bagaimana mereka bisa masuk? ... Apa yang kita lakukan? Kita kacau jika bos tahu...",
  ui_story_5023_50230101_39X_dialog_content = "Di sini, di tongkat, tidak ada yang akan tahu jika kita menggunakan ramuan penambah untuk berubah menjadi Eclipsites.",
  ui_story_5023_50230101_39X1_dialog_content = "Ayo, tenggak ini dan mari singkirkan mereka!",
  ui_story_5023_50230101_40_dialog_content = "... Sepertinya kita punya masalah.",
  ui_story_5023_50230101_41_dialog_content = "Terserah, kurasa penyamaranku tidak akan terbongkar jika aku menyingkirkan semua orang.",
  ui_story_5023_50230101_42_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5023_50230101_43_dialog_content = "Graah!",
  ui_story_5023_50230101_44_dialog_content = "... Gerhana? Mengapa Umbraton memiliki—",
  ui_story_5023_50230101_45_dialog_content = "Ahh!",
  ui_story_5023_50230101_46_dialog_content = "Acer!",
  ui_story_5023_50230101_47_dialog_content = "<color=#e8d9bb>Swish… Dhuar!</color>",
  ui_story_5023_50230101_48_dialog_content = "Gaah…",
  ui_story_5023_50230101_49_dialog_content = "Acer!",
  ui_story_5023_50230101_50_dialog_content = "Javier! *Menangis*",
  ui_story_5023_50230101_51_dialog_content = "Kenapa kau tidak bisa mendengarkanku saja? Saya mengatakan kepada Anda untuk tinggal di sana!",
  ui_story_5023_50230101_52_dialog_content = "Tapi... Tapi... Wanita berambut abu-abu itu sangat menakutkan...",
  ui_story_5023_50230101_53_dialog_content = "Gadis Kecil, wanita berambut kelabu yang menyeramkan ini baru saja menyelamatkan nyawamu.",
  ui_story_5023_50230101_54_dialog_content = "Jangan mendekat!",
  ui_story_5023_50230101_55_dialog_content = "Heh, coba hentikan aku.",
  ui_story_5023_50230101_56_dialog_content = "Kumohon... Tolong jangan sakiti saudaraku!",
  ui_story_5023_50230101_57_dialog_content = "Dia membutuhkan uang untuk mengobati penyakitku dan akhirnya tertipu untuk bergabung dengan Blue Lion Guild!",
  ui_story_5023_50230101_58_dialog_content = "Setiap kali dia pergi bekerja, saya dikunci di gudang oleh orang-orang yang tampak menakutkan ini...",
  ui_story_5023_50230101_59_dialog_content = "Jika dia berhutang padamu, aku berjanji akan membayarmu kembali!",
  ui_story_5023_50230101_60_dialog_content = "Kumohon... Jangan sakiti saudaraku...",
  ui_story_5023_50230101_61_dialog_content = "...",
  ui_story_5023_50230101_62_dialog_content = "Trik kotor seperti menggunakan orang yang dicintai sebagai sandera pasti sejalan dengan perilaku yang diharapkan dari guild kelas tiga itu.",
  ui_story_5023_50230101_63_dialog_content = "Pernahkah Anda berpikir tentang apa yang akan terjadi pada saudara perempuan Anda jika Anda meninggal?",
  ui_story_5023_50230101_64_dialog_content = "… Aku…",
  ui_story_5023_50230101_65_dialog_content = "Kebalikan dari bertindak gegabah dan menyerang langsung menuju kematian, Anda harus menggunakan otak Anda dan mencari cara untuk bertahan hidup dengannya.",
  ui_story_5023_50230101_66_dialog_content = "Nih, ambil.",
  ui_story_5023_50230101_67_dialog_content = "Apa isi tas ini?",
  ui_story_5023_50230101_68_dialog_content = "Anda bahkan tidak bisa membedakan suara Nightium? Bagaimana Anda bodoh Blue Lion Guild bahkan berhasil di Umbraton adalah di luar saya.",
  ui_story_5023_50230101_69_dialog_content = "Ini tanggung jawab saya untuk memastikan bahwa kekayaan yang tidak layak di tangan Anda pergi ke tempatnya.",
  ui_story_5023_50230101_70_dialog_content = "Akhirnya, saya akan menemukan apa yang saya cari. Ketika saat itu tiba, saya membayangkan petinggi Anda akan mengejar Anda.",
  ui_story_5023_50230101_71_dialog_content = "Belum terlambat untuk berlari.",
  ui_story_5023_50230101_72_dialog_content = "Tunggu!",
  ui_story_5023_50230101_73_dialog_content = "… Kenapa kau membantuku?",
  ui_story_5023_50230101_74_dialog_content = "Itu bukan urusan Anda. Cepatlah sebelum aku berubah pikiran.",
  ui_story_5023_50230101_75_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5023_50230101_76_dialog_content = "Sebuah ledakan! Terdengar suara ledakan dari sekitar gudang! Semuanya pergi dan lihatlah!",
  ui_story_5023_50230101_76X_dialog_content = "Bagus... Semua penjaga ditarik pergi. Tidak buruk. Saya kira anak itu lebih cerdas dari yang saya kira.",
  ui_story_5023_50230101_77_dialog_content = "...",
  ui_story_5023_50230101_78_dialog_content = "Abang, ya...",
  ui_story_5023_50230101_79_dialog_content = "Setelah itu, Acer dan saya lari dari satu tempat ke tempat lain dengan bantuan uang Azure memberi saya.",
  ui_story_5023_50230101_80_dialog_content = "Tidak lama kemudian, konspirasi Blue Lion Guild terungkap. Shadowlord menangani mereka, dan kami akhirnya bebas dari para pengejar kami.",
  ui_story_5023_50230101_81_dialog_content = "Saya bertanya tentang Nona Azure ke mana-mana dan belajar tentang banyak tindakan heroik yang dia lakukan, yang mendorong saya untuk ingin bergabung dengan Rediesel Wrench.",
  ui_story_5023_50230101_82_dialog_content = "Oh, jadi begitukah Anda kehilangan dompet saat Anda pergi ke Umbraton untuk membeli kalung untuk Kafka's Franz?",
  ui_story_5023_50230101_83_dialog_content = "Mengapa itu penting? Saya membawa kembali kargo dan menjual intelijen dengan harga bagus, bukan?",
  ui_story_5023_50230101_84_dialog_content = "Anda memberi kami kesempatan kedua dalam hidup, dan saya ingin menggunakannya untuk membalas kebaikan Anda.",
  ui_story_5023_50230101_85_dialog_content = "Tidak perlu. Saya menikmati sendirian, dan saya tidak membutuhkan rasa terima kasih dari siapa pun.",
  ui_story_5023_50230101_86_dialog_content = "Aku hanya butuh mobilku, senjataku dan... mungkin juga seekor anjing seperti milik Kafka.",
  ui_story_5023_50230101_87_dialog_content = "Azure, tolong terimalah aku sebagai anjingmu!",
  ui_story_5023_50230101_88_dialog_content = "Tunggu sebentar!",
  ui_story_5023_50230101_89_dialog_content = "Perhatikan bahasa Anda! Kami punya anak di bawah umur di sini!",
  ui_story_5023_50230101_90_dialog_content = "Hmm? Apakah dia mengatakan sesuatu yang tidak cocok untuk anak di bawah umur?",
  ui_story_5023_50230101_91_dialog_content = "Kami bukan anak-anak lagi! Beri tahu kami maksud Anda, beri tahu kami maksud Anda!",
  ui_story_5023_50230101_92_dialog_content = "Kudengar dia menyebut anjing… Memangnya ada anak anjing yang hilang?",
  ui_story_5023_50230101_93_dialog_content = "Itu benar. Sebelum bertemu Ny Azure, Saya tersesat dalam hidup, seperti tersesat—",
  ui_story_5023_50230101_94_dialog_content = "Ehem!",
  ui_story_5023_50230101_95_dialog_content = "Sudah kubilang jaga bicaramu!",
  ui_story_5023_50230101_96_dialog_content = "Kalian bertiga! Pergi cuci tangan, makan malam hampir siap!",
  ui_story_5023_50230101_97_dialog_content = "Baiklah…",
  ui_story_5023_50230101_98_dialog_content = "Pria muda yang lugas. Menarik.",
  ui_story_5023_50230101_99_dialog_content = "Sejujurnya, maukah Anda berhenti memikat pria muda ke kiri dan ke kanan? Ketika mereka tidak dapat menemukan Anda, mereka menjadi masalah saya.",
  ui_story_5023_50230101_100_dialog_content = "U-Um... Azure.",
  ui_story_5023_50230101_101_dialog_content = "Ah, itu Acer, bukan? Apa kabarmu? Merasa lebih baik?",
  ui_story_5023_50230101_102_dialog_content = "Iya. Sekarang aku sudah sembuh…",
  ui_story_5023_50230101_103_dialog_content = "Juga, saya belajar banyak hal saat bepergian dengan Karavan dan bahkan menghemat sejumlah uang untuk membantu para pedagang...",
  ui_story_5023_50230101_104_dialog_content = "I-Itu tidak cukup untuk membayar Nona Azure kembali uang yang Anda pinjamkan kepada kami, tetapi saya akan terus bekerja keras!",
  ui_story_5023_50230101_105_dialog_content = "Aku tidak pernah bermaksud agar kamu... Sudahlah.",
  ui_story_5023_50230101_106_dialog_content = "Pada akhirnya, Rediesel Wrench hanyalah sekelompok udik yang tidak berbudaya yang terlibat perkelahian hari demi hari.",
  ui_story_5023_50230101_107_dialog_content = "Saya pikir Anda akan lebih baik bekerja sebagai pelayan di Squirming Sandworm. Saya mengenal pemiliknya dengan baik dan saya akan memastikan dia memperlakukan Anda dengan benar.",
  ui_story_5023_50230101_108_dialog_content = "Adapun kakakmu... Aku ragu dia bisa menangani pukulan dari Roy, tapi dia masih punya cukup waktu untuk bekerja sebagai keamanan di sana.",
  ui_story_5023_50230101_109_dialog_content = "Setelah Anda menguasai semua minuman campuran spesial mereka, buka kedai minuman di Oasis kami.",
  ui_story_5023_50230101_110_dialog_content = "Oke!",
  ui_story_5023_50230101_111_dialog_content = "Anda benar-benar berusaha keras untuk mendapatkan minuman gratis...",
  ui_story_5023_50230101_112_dialog_content = "Aku sangat lapar tiba-tiba. Apa untuk makan malam?",
  ui_story_5023_50230101_113_dialog_content = "Wah, itu pengalihan topik yang sangat buruk.",
  ui_story_5023_50230101_114_dialog_content = "… Aku memasak unta kukus dengan bawang gurun.",
  ui_story_5023_50230201_1_dialog_content = "...",
  ui_story_5023_50230201_2_dialog_content = "... Bagus sekali. Dia tidak ada. Sekarang saatnya.",
  ui_story_5023_50230201_3_dialog_content = "Azure?",
  ui_story_5023_50230201_4_dialog_content = "... Sial, aku tertangkap!",
  ui_story_5023_50230201_5_dialog_content = "Kenapa kamu pincang? Apakah kamu terluka?",
  ui_story_5023_50230201_6_dialog_content = "Diam... Diam. Jangan biarkan Roy mendengarmu.",
  ui_story_5023_50230201_7_dialog_content = "Saya tidak akan pernah memenangkan argumen melawannya lagi jika dia tahu saya terluka saat penyergapan.",
  ui_story_5023_50230201_8_dialog_content = "Jadi kau... mencoba menyelundupkan perlengkapan P3K? Aku akan membantumu mengobati lukamu.",
  ui_story_5023_50230201_9_dialog_content = "Nah, itu hanya luka di permukaan. Plus Anda sedang menuju keluar dengan Sinsa, bukan?",
  ui_story_5023_50230201_10_dialog_content = "Tapi aku punya minuman keras.",
  ui_story_5023_50230201_11_dialog_content = "… Sepakat.",
  ui_story_5023_50230201_12_dialog_content = "Yah, itu tidak seburuk kelihatannya. Sebagian besar darah itu bukan milikmu, jadi kamu seharusnya baik-baik saja.",
  ui_story_5023_50230201_13_dialog_content = "Saya merasa seperti saya tidak mendapatkan banyak perawatan atau perhatian dari Anda hari ini. Tidak lagi mencintaiku?",
  ui_story_5023_50230201_14_dialog_content = "Apakah Anda kebetulan memukul kepala Anda? Karena sepertinya begitu. Mungkin aku harus menelepon Roy untuk melihat-lihat.",
  ui_story_5023_50230201_15_dialog_content = "Aku hanya main-main, kok. Bercanda!",
  ui_story_5023_50230201_16_dialog_content = "Ini mungkin akan sedikit menyakitkan. Bersabarlah denganku.",
  ui_story_5023_50230201_17_dialog_content = "Sangat jarang bagi Anda untuk jatuh ke dalam perangkap seseorang.",
  ui_story_5023_50230201_18_dialog_content = "Anda seharusnya melihat bagaimana lawan saya berakhir.",
  ui_story_5023_50230201_19_dialog_content = "Saya percaya burung nasar pasti memakan sisa-sisa anak nakal rendahan itu sekarang.",
  ui_story_5023_50230201_20_dialog_content = "Pemimpin kelompok tersebut mengaku sebagai orang yang selamat dari geng yang telah disingkirkan oleh Rediesel Wrench di masa lalu.",
  ui_story_5023_50230201_21_dialog_content = "Geng yang mana, ya?",
  ui_story_5023_50230201_22_dialog_content = "Aku juga menanyakan itu.",
  ui_story_5023_50230201_23_dialog_content = "Kami telah menyingkirkan begitu banyak geng selama bertahun-tahun, bagaimana kami bisa mengingat semua nama mereka?",
  ui_story_5023_50230201_24_dialog_content = "Ah, tapi aku ingat Death Row. Pertikaian Anda dengan pemimpin mereka benar-benar luar biasa.",
  ui_story_5023_50230201_25_dialog_content = "Itu saja... Lagi pula, sudah bertahun-tahun.",
  ui_story_5023_50230201_26_dialog_content = "Anda seharusnya melihat raut wajah pria botak itu ketika saya mengatakan kepadanya bahwa saya tidak dapat mengingat gengnya sama sekali, itu lucu.",
  ui_story_5023_50230201_27_dialog_content = "Namun... Yah. Karena dia mengenal kita...",
  ui_story_5023_50230201_28_dialog_content = "Dia memancingku dengan informasi tentang penyintas Balsa.",
  ui_story_5023_50230201_29_dialog_content = "Jadi begitu. Itu satu hal yang akan Anda selidiki meskipun tahu itu bisa menjadi jebakan.",
  ui_story_5023_50230201_30_dialog_content = "Tidak ada risiko yang tidak ingin saya ambil jika ada kemungkinan itu akan membawa saya ke saudara laki-laki saya.",
  ui_story_5023_50230201_31_dialog_content = "Bukankah seharusnya kau membawa seseorang bersamamu di saat-saat seperti ini?",
  ui_story_5023_50230201_32_dialog_content = "Aduh. Tenanglah.",
  ui_story_5023_50230201_33_dialog_content = "Keterampilan keperawatan Anda belum meningkat sama sekali.",
  ui_story_5023_50230201_34_dialog_content = "Anda tahu saya tidak sering terluka, sama seperti Anda. Saya jarang memiliki kesempatan untuk berlatih.",
  ui_story_5023_50230201_35_dialog_content = "Omong-omong, itu hal yang baik.",
  ui_story_5023_50230201_36_dialog_content = "Baiklah, saya sudah selesai.",
  ui_story_5023_50230201_37_dialog_content = "Ini dia. Beberapa barang bagus dari Jomu. Aku telah menyimpannya hanya untukmu. Di Batu?",
  ui_story_5023_50230201_38_dialog_content = "Mmm... Cantik!",
  ui_story_5023_50230201_39_dialog_content = "Dan duduk di sini, Anda mendapatkan pemandangan Oasis yang indah. Aku menyukainya.",
  ui_story_5023_50230201_40_dialog_content = "Bahu Anda begitu nyaman untuk bersandar.",
  ui_story_5023_50230201_41_dialog_content = "...",
  ui_story_5023_50230201_42_dialog_content = "Aku harus hidup, meski hanya untuk saat-saat ini. Untuk bertahan hidup, dan kembali.",
  ui_story_5023_50230201_43_dialog_content = "Yah, yang penting kau tahu itu.",
  ui_story_5023_50230201_44_dialog_content = "Mari minum sepuasnya hari ini!",
  ui_story_5023_50230201_45_dialog_content = "Hm... dengan senang hati.",
  ui_story_5023_50230301_1_dialog_content = "Tim sudah siap, bahan dan hadiah... dikonfirmasi.",
  ui_story_5023_50230301_2_dialog_content = "Hebat. Kami akhirnya mendapatkan sesuatu selain Serbuk Protein Serangga Jomu dan boneka acak tahun ini sebagai hadiah.",
  ui_story_5023_50230301_3_dialog_content = "Jomu di mana, ya…?",
  ui_story_5023_50230301_4_dialog_content = "Tiny One menggantungnya karena mengambil terlalu banyak ruang di gudang, dia mungkin memohon belas kasihan sekarang.",
  ui_story_5023_50230301_5_dialog_content = "Odi, kamu kembali! Poin komunikasi untuk semua tahapan ditetapkan?",
  ui_story_5023_50230301_6_dialog_content = "Tentu saja sudah. Gampang sekali, kok.",
  ui_story_5023_50230301_7_dialog_content = "Tahu tidak berapa banyak kegagalan teknis remeh-temeh yang harus kutangani untuk para orang dungu itu setiap harinya?",
  ui_story_5023_50230301_8_dialog_content = "Lebih dari separuh masalah mereka selalu diperbaiki hanya dengan memulai ulang! Terus terang, otak mereka yang perlu diservis—",
  ui_story_5023_50230301_9_dialog_content = "Err... maafkan aku. Saya berbicara terlalu banyak.",
  ui_story_5023_50230301_10_dialog_content = "Anda mungkin satu-satunya yang lebih sibuk dari saya di seluruh Rediesel Wrench.",
  ui_story_5023_50230301_11_dialog_content = "Kapan Tiny One, Fleur dan tangan saya penuh, Anda selalu menjadi orang yang kami minta bantuan...",
  ui_story_5023_50230301_12_dialog_content = "Haha, aku bukan profesional. Saya menganggapnya sebagai keajaiban saya tidak berakhir menyebabkan lebih banyak masalah.",
  ui_story_5023_50230301_13_dialog_content = "Anda disana, Roy! Pemeliharaan dan pengujian Lepidoz selesai.",
  ui_story_5023_50230301_14_dialog_content = "Dengan begitu banyak rediesel di perutnya, seharusnya Lepidoz bisa mengikuti kontestan kita sampai akhir lomba tanpa masalah.",
  ui_story_5023_50230301_15_dialog_content = "Sangat berguna Odi juga ada di sini! Kami memiliki beberapa hal untuk diperiksa dengan Anda mengenai pengaturan komunikasi radio Lepidoz...",
  ui_story_5023_50230301_16_dialog_content = "Roy!",
  ui_story_5023_50230301_17_dialog_content = "Ada apa, Pemimpin?",
  ui_story_5023_50230301_17X_dialog_content = "Wow!",
  ui_story_5023_50230301_18_dialog_content = "Bisakah Anda menghentikan Zeta menambahkan begitu banyak detail aneh ke kepribadian saya ?!",
  ui_story_5023_50230301_19_dialog_content = "Saya tidak keberatan menjadi pengamuk tetapi mengapa saya harus \"bercerai tiga kali\"?",
  ui_story_5023_50230301_20_dialog_content = "Er, mundur sedikit dulu, ya? Kami berdua orang tua berdiri dengan wajah kami begitu dekat bersama-sama akan menyebabkan keributan.",
  ui_story_5023_50230301_21_dialog_content = "Aku bukan orang tua!",
  ui_story_5023_50230301_22_dialog_content = "Tentu, tentu, berikan beberapa tahun lagi.",
  ui_story_5023_50230301_23_dialog_content = "Bagaimanapun, tampaknya Anda bermain peran dengan baik untuk Zeta, tetapi Anda tidak senang dengan peran Anda.",
  ui_story_5023_50230301_24_dialog_content = "Kami tidak semua suka berkeliling menjawab apa pun yang Zeta panggil kami, tidak seperti beberapa orang... Putri.",
  ui_story_5023_50230301_25_dialog_content = "Jangan salah paham! Saya menemukan peran putri sangat menantang. Pasti salah satu dari tiga karakter sulit untuk dimainkan.",
  ui_story_5023_50230301_26_dialog_content = "Jika Anda dapat mengubah kepribadian Anda, apa yang akan Anda pilih? Jangan bilang kau akan menggunakan Shinnosuke...",
  ui_story_5023_50230301_27_dialog_content = "Saya belum menggunakan cerita-cerita itu sebagai dongeng pengantar tidur untuk anak-anak.",
  ui_story_5023_50230301_28_dialog_content = "Zeta mudah dipengaruhi. Jika saya melakukannya, tidak akan butuh waktu lama baginya untuk mengubah peran Anda menjadi pengelana pengembara dari Timur Jauh yang memegang pedang iblis.",
  ui_story_5023_50230301_29_dialog_content = "... Kamu sudah membaca serial itu juga?",
  ui_story_5023_50230301_30_dialog_content = "Apa Anda sedang bercanda? Semua benteng tahu.",
  ui_story_5023_50230301_31_dialog_content = "Anda tampaknya telah membeli banyak salinan untuk dikirim ke orang-orang, lalu secara obsesif mengejar mereka menanyakan tentang karakter favorit mereka.",
  ui_story_5023_50230301_32_dialog_content = "Itu benar, tapi kau membuatku terdengar begitu...",
  ui_story_5023_50230301_33_dialog_content = "\"Aku akan membunuh seribu penjahat di dunia ini untuk menjaga keamanan adikku selama sisa hidupnya!\"",
  ui_story_5023_50230301_34_dialog_content = "Anda tidak perlu berteriak itu!",
  ui_story_5023_50230301_35_dialog_content = "Apa yang harus dipermalukan? Jangan lupa aku sudah membaca semua puisi yang kau tulis saat kecil. Itu bahkan lebih...",
  ui_story_5023_50230301_36_dialog_content = "Ngomong-ngomong, saya sedang membersihkan gudang beberapa hari yang lalu dan menemukan beberapa koleksi puisi lagi.",
  ui_story_5023_50230301_37_dialog_content = "Apa?!",
  ui_story_5023_50230301_38_dialog_content = "Jangan berani-berani menunjukkannya Azure! Anda tidak tahu berapa lama dia menggoda saya tentang hal itu sesudahnya!",
  ui_story_5023_50230301_39_dialog_content = "Ahahah. Setelah bertahun-tahun, Anda masih tidak tahu bagaimana menanganinya.",
  ui_story_5023_50230301_40_dialog_content = "Hmm…",
  ui_story_5023_50230301_41_dialog_content = "Ini adalah kesempatan yang sangat langka. Apakah Anda ingin bekerja sama dengan Azure untuk reli tahun ini?",
  ui_story_5023_50230301_42_dialog_content = "Terkadang saya benar-benar tidak tahu apakah Anda bercanda atau tidak... apakah ini yang Anda sebut terapi pemaparan?",
  ui_story_5023_50230301_43_dialog_content = "Tapi selain itu Azure, siapa lagi yang lebih cocok untuk ditampilkan PlayerName teknik balap Rediesel Wrench?",
  ui_story_5023_50230301_44_dialog_content = "… Benar juga.",
  ui_story_5023_50230301_45_dialog_content = "Tapi pertama-tama, beri saya koleksi puisi yang Anda temukan.",
  ui_story_5023_50230301_46_dialog_content = "Hmm… Bagaimana, ya?",
  ui_story_5023_50230301_47_dialog_content = "Anda tahu cara kerja Rediesel Wrench: pertama datang, pertama dilayani, penemu, penjaga.",
  ui_story_5023_50230301_48_dialog_content = "Kecuali, tentu saja, Anda memerintahkan saya sebagai pemimpin saya... atau jika Anda dapat mengambilnya dari saya dengan paksa—",
  ui_story_5023_50230301_49_dialog_content = "... Aku tidak akan menahannya!",
  ui_story_5023_50230301_50_dialog_content = "Aww... betapa menakutkannya.",
  ui_story_5023_50230301_51_dialog_content = "Bukankah PlayerName menunggumu? Tidak baik membuat tamu menunggu.",
  ui_story_5023_50230301_52_dialog_content = "Sudah terlambat untuk menarik kembali kata-katamu, Roy.",
  ui_story_5023_50230301_53_dialog_content = "Berubah pikiran? Mana mungkin! Waktumu cuma satu menit. Kalau kau bisa merebut buku catatan ini, kau boleh ambil puisinya.",
  ui_story_5023_50230301_54_dialog_content = "Kalau tidak, coba pertimbangkan dengan serius untuk ikut balapan dengan Azure.",
  ui_story_5023_50230301_55_dialog_content = "Dia sudah muak dengan omelanku. Salah satu dari kalian mungkin bisa menghubunginya...",
  ui_story_5023_50230301_56_dialog_content = "Kau mengatakan sesuatu?",
  ui_story_5023_50230301_57_dialog_content = "Ahh… Bukan apa-apa.",
  ui_story_5023_50230301_58_dialog_content = "Anda memiliki 50 detik tersisa, Pemimpin.",
  ui_story_5023_50230301_59_dialog_content = "Itu curang!",
  ui_story_5023_50230301_60_dialog_content = "Aduh… Sekujur tubuhku sakit… Tiny One memang kejam…",
  ui_story_5023_50230301_61_dialog_content = "Hmm? Sebuah perkelahian?",
  ui_story_5023_50230301_62_dialog_content = "Wah! Dia menghindari kunci pas bos dan pergi begitu cepat!",
  ui_story_5023_50230301_63_dialog_content = "Roy jelas bukan seseorang yang ingin kamu ganggu... Apa yang terjadi dengan mereka?",
  ui_story_5023_50230301_64_dialog_content = "Hah? Saya tidak memperhatikan. Anda lebih baik merawat kepala bengkak Anda sebelum Anda mulai ikut campur dalam urusan orang lain. Sungguh, Anda tidak pernah belajar pelajaran Anda.",
  ui_story_5023_50230301_65_dialog_content = "Saya mendengar Zeta. Dan sesuatu tentang mengambil notepad dalam satu menit. ...Itu dia.",
  ui_story_5023_50230301_66_dialog_content = "Saya berani bertaruh satu Tool Kit bahwa dalam pertempuran keterampilan alih-alih stamina, Boss tidak memiliki peluang.",
  ui_story_5023_50230301_67_dialog_content = "Saya keluar. Saya tidak bodoh.",
  ui_story_5023_50230301_68_dialog_content = "Hmm. Saya punya tajuk utama yang bagus untuk Umbraton Daily.",
  ui_story_5023_50230301_69_dialog_content = "\"Konflik antara Rediesel Wrench Leader dan Anggota Senior atas Pelatihan Bakat Baru!\"",
  ui_story_5023_50230301_70_dialog_content = "Saya bertanya-tanya berapa banyak orang Nightium akan membayar untuk membaca itu...",
  ui_story_5023_50230401_1_dialog_content = "Apakah benar-benar tidak ada pilihan lain?",
  ui_story_5023_50230401_2_dialog_content = "Ayo, percayakan ini padaku. Pai Kalajengking Merah sangat baik.",
  ui_story_5023_50230401_3_dialog_content = "Karena Anda seorang VIP, koki membuatnya spesial hanya untuk Anda. Milik Anda tidak hanya memiliki Deep Fried Flare Scorpion, tetapi juga termasuk bonus Roasted Crimson Ring Snake.",
  ui_story_5023_50230401_4_dialog_content = "Apakah ini dimaksudkan sebagai dorongan?",
  ui_story_5023_50230401_5_dialog_content = "Dua-duanya terdengar mematikan!",
  ui_story_5023_50230401_6_dialog_content = "Jangan takut! Tarik kepala dan pantat dan nikmatilah!",
  ui_story_5023_50230401_7_dialog_content = "Yang terkuat bertahan. Aturan terkuat. Beginilah cara kerja kehidupan di gurun.",
  ui_story_5023_50230401_8_dialog_content = "Anda mengkonsumsi pai ini dengan menghormati nyawa makhluk yang dikalahkan yang digunakan untuk membuatnya, hidup mereka menjadi bagian dari darah dan daging Anda, dan begitulah hidup terus berjalan.",
  ui_story_5023_50230401_9_dialog_content = "Pidatomu sangat puitis dan menyentuh, tapi aku...",
  ui_story_5023_50230401_10_dialog_content = "Anak muda, bagaimana kalau kau mencicipi sup dulu sebagai hidangan pembuka?",
  ui_story_5023_50230401_11_dialog_content = "Terima kasih!",
  ui_story_5023_50230401_12_dialog_content = "*Batuk*... Apa-apaan ini?",
  ui_story_5023_50230401_13_dialog_content = "Sup Sandworm dan Belalang!",
  ui_story_5023_50230401_14_dialog_content = "Wow, nama yang sangat lugas.",
  ui_story_5023_50230401_15_dialog_content = "Tunggu dulu, saya pernah mendengarnya sebelumnya... apakah itu ada di buku?",
  ui_story_5023_50230401_16_dialog_content = "Ha, kamu cukup berbudaya!",
  ui_story_5023_50230401_17_dialog_content = "Ini adalah kelezatan gurun yang terkenal. Rupanya, beberapa koki dari daerah lain telah mencoba memperbanyaknya bahkan ketika mereka tidak bisa mendapatkan semua bahan penting.",
  ui_story_5023_50230401_18_dialog_content = "\"Tambahkan paprika asap dan belalang goreng. Taburi dengan satu sendok makan saus sambal...\"",
  ui_story_5023_50230401_19_dialog_content = "Apakah Anda kebetulan menyajikan Nasi Batu Pasir?",
  ui_story_5023_50230401_20_dialog_content = "Bagaimana Anda tahu hidangan spesial pemiliknya? Itu bahkan tidak ada di menu!",
  ui_story_5023_50230401_21_dialog_content = "Saya kira dia harus benar-benar menikmati masakan gurun kami. Belikan dia sebotol susu unta lagi.",
  ui_story_5023_50230401_22_dialog_content = "Apa restoran ini milik Paman Johnny?",
  ui_story_5023_50230401_23_dialog_content = "Ohh? Pernah lihat Resep Rediesel juga?",
  ui_story_5023_50230401_24_dialog_content = "Yang benar saja!",
  ui_story_5023_50230401_25_dialog_content = "Aku sudah ingin bertemu dengannya sejak aku membaca bukunya...",
  ui_story_5023_50230401_26_dialog_content = "Mengapa Anda tidak mengatakan sesuatu sebelumnya? Johnny sedang berkeliling dunia mencari inspirasi baru.",
  ui_story_5023_50230401_27_dialog_content = "Dia tidak akan kembali untuk Blazing Rally.",
  ui_story_5023_50230401_28_dialog_content = "Johnny adalah salah satu dari sedikit anggota di sini yang tidak begitu tertarik dengan balapan.",
  ui_story_5023_50230401_29_dialog_content = "Yang dipikirkannya hanya makanan.",
  ui_story_5023_50230401_30_dialog_content = "Aku yakin dia sedang menyergap di luar sarang Eclipsite, berburu Eclipsites yang lezat.",
  ui_story_5023_50230401_31_dialog_content = "Eclipsite bisa dimakan?!",
  ui_story_5023_50230401_32_dialog_content = "Sekarang setelah kupikir-pikir, dia mengaku sebagai pencicip daging Eclipsite dalam bukunya...",
  ui_story_5023_50230401_33_dialog_content = "Sayang sekali Anda tidak bisa bertemu dengannya kali ini. Tapi makanan akan... ada apa lagi?",
  ui_story_5023_50230401_34_dialog_content = "Ah, benar. Makanan akan menghubungkan kalian berdua melampaui ruang dan waktu.",
  ui_story_5023_50230401_35_dialog_content = "Omong-omong, aku tidak hanya menariknya keluar dari pantatku. Itulah yang selalu dikatakan Johnny.",
  ui_story_5023_50230401_36_dialog_content = "Dia berencana mencetaknya di halaman sampul edisi lanjutan Rediesel Recipe.",
  ui_story_5023_50230401_37_dialog_content = "(Vice juga suka mencoba bahan-bahan yang tidak biasa... tetapi masakannya lebih seperti senjata mematikan daripada makanan sebenarnya.)",
  ui_story_5023_50230401_38_dialog_content = "(Tapi ini adalah kesempatan saya untuk mengalami semua hal menarik dari buku ini!)",
  ui_story_5023_50230401_39_dialog_content = "(Skenario terburuk, perjalanan saya berakhir dengan keracunan makanan pada malam sebelum balapan...)",
  ui_story_5023_50230401_40_dialog_content = "Oke! Saya akan makan!",
  ui_story_5023_50230401_41_dialog_content = "...",
  ui_story_5023_50230401_42_dialog_content = "(Ah! Entah bagaimana, aku masih hidup. Dan...)",
  ui_story_5023_50230401_43_dialog_content = "... Ini ... rasanya cukup enak.",
  ui_story_5023_50230401_44_dialog_content = "Ya! Kau menyukainya!",
  ui_story_5023_50230401_45_dialog_content = "Benar. Kalajengking ini terasa sangat renyah di luar dan sangat lembut serta berlemak di dalam. Bumbu pedas dan masamnya luar biasa…",
  ui_story_5023_50230401_46_dialog_content = "... Dengarkan kata-kata indah itu! Apakah Anda mendapatkan semua itu dari buku yang Anda baca?",
  ui_story_5023_50230401_47_dialog_content = "Saya tau? Tidak seperti kita. Kami hanya pandai menjejali wajah kami dan berkata, \"Sial, itu bagus!\"",
  ui_story_5023_50230401_48_dialog_content = "Mendesah. Saya berharap Johnny bisa mendengar ini untuk dirinya sendiri.",
  ui_story_5023_50230401_49_dialog_content = "… PlayerName.",
  ui_story_5023_50230401_50_dialog_content = "Ya?",
  ui_story_5023_50230401_51_dialog_content = "Apakah Anda tertarik untuk mencoba dan mengulas semua yang dimiliki restoran? Itu benar-benar akan membuat Johnny bahagia.",
  ui_story_5023_50230401_52_dialog_content = "Err... Saya sarankan kita menyimpannya untuk lain kali. Selera saya berada pada batasnya untuk hari ini ...",
  ui_story_5023_50230401_53_dialog_content = "Pesta perayaan akan berlangsung di akhir lomba. Anda tidak akan bisa mendapatkan detik di sana.",
  ui_story_5023_50230401_54_dialog_content = "Benarkah?",
  ui_story_5023_50230401_55_dialog_content = "(Saya sedikit kecewa tapi juga sedikit lega...)",
  ui_story_5023_50230401_56_dialog_content = "Hei, jangan khawatir! Roy bertanggung jawab atas pesta perayaan.",
  ui_story_5023_50230401_57_dialog_content = "Ini akan menjadi petualangan mendebarkan lainnya untuk selera Anda, hampir sama mendebarkannya dengan hidangan Johnny!",
  ui_story_5023_50230401_58_dialog_content = "Apakah makan selalu merupakan petualangan dengan Rediesel Wrench?",
  ui_story_5023_50230401_59_dialog_content = "Baiklah, kamu pasti haus setelah semua pembicaraan ini.",
  ui_story_5023_50230401_60_dialog_content = "Minumlah jus buah busuk lidah naga ini dan selanjutnya kita akan mencoba menu rahasianya!",
  ui_story_5023_50230401_61_dialog_content = "Um... Termasuk beras batu pasir?",
  ui_story_5023_50230401_62_dialog_content = "(Ini akan menjadi malam yang panjang...)",
  ui_story_5023_50230501_1_dialog_content = "Hmm... Aku... Aku tidak bisa melihat apa yang ada di depan...",
  ui_story_5023_50230501_2_dialog_content = "Suara ini… Zeta? Untuk apa semua pakaian ini?",
  ui_story_5023_50230501_3_dialog_content = "Woah!",
  ui_story_5023_50230501_4_dialog_content = "Aku harus cepat-cepat mengambilnya.",
  ui_story_5023_50230501_5_dialog_content = "Eh… Zeta mau mencuci baju!",
  ui_story_5023_50230501_6_dialog_content = "Ini semua adalah pakaianku!",
  ui_story_5023_50230501_7_dialog_content = "Jona, apakah Anda melihat pakaian dan topi yang saya gantung di luar?",
  ui_story_5023_50230501_8_dialog_content = "Tidak.",
  ui_story_5023_50230501_9_dialog_content = "Tunggu... Tadi aku melihat Zeta dengan seikat pakaian. Dia mungkin meraih milikmu secara tidak sengaja.",
  ui_story_5023_50230501_10_dialog_content = "Bagaimana, ketika dia setengah ukuran saya?",
  ui_story_5023_50230501_11_dialog_content = "Saya tidak tahu tentang itu. Beberapa atasan Anda cukup pendek. Ngomong-ngomong, cintai mereka.",
  ui_story_5023_50230501_12_dialog_content = "Heh... Meskipun aku ingin tinggal dan mendengarkan sanjunganmu, aku benar-benar harus pergi mencari Zeta.",
  ui_story_5023_50230501_13_dialog_content = "Teruskan. Ini tidak seperti aku akan cemburu atau apapun.",
  ui_story_5023_50230501_14_dialog_content = "Ugh... apakah ini... seharusnya seperti ini? Apa pun!",
  ui_story_5023_50230501_15_dialog_content = "Ah! O-Oh tidak! Bahkan saya tahu itu tidak benar ...",
  ui_story_5023_50230501_16_dialog_content = "Mungkin saya akan menghapusnya? ... Ini bahkan lebih buruk sekarang!",
  ui_story_5023_50230501_17_dialog_content = "Berdasarkan Barbara, merias wajah itu seperti menggambar, tapi kenapa...",
  ui_story_5023_50230501_18_dialog_content = "Anda benar-benar harus bertanya? Apakah Anda lupa betapa buruknya Anda dalam menggambar?",
  ui_story_5023_50230501_19_dialog_content = "<size=45>Aaaah!</size>",
  ui_story_5023_50230501_20_dialog_content = "A-Azure? Apa yang membawamu kemari?!",
  ui_story_5023_50230501_21_dialog_content = "Berhenti di sana. Ini adalah markas rahasia pahlawan wanita. Jika pesuruh iblis memaksa masuk—",
  ui_story_5023_50230501_22_dialog_content = "<size=45>Akan kuhabisi!</size>",
  ui_story_5023_50230501_23_dialog_content = "Hmm? Bukankah seharusnya Anda menatap mata seseorang ketika Anda berbicara dengan mereka?",
  ui_story_5023_50230501_24_dialog_content = "Um... u-uh... Ahem! *batuk* Aku sedang flu dan tidak ingin menularkannya padamu...",
  ui_story_5023_50230501_25_dialog_content = "Aduh, tiba-tiba sakit ya? Jangan beri aku itu, idiot jangan sakit.",
  ui_story_5023_50230501_26_dialog_content = "Berbaliklah untukku.",
  ui_story_5023_50230501_27_dialog_content = "<size=45>T-Tunggu! Bisakah Anda berjanji bahwa Anda tidak akan tertawa?</size>",
  ui_story_5023_50230501_28_dialog_content = "Kau kan tahu aku tak mudah tertawa.",
  ui_story_5023_50230501_29_dialog_content = "...",
  ui_story_5023_50230501_30_dialog_content = "Pfft…",
  ui_story_5023_50230501_31_dialog_content = "Anda berjanji tidak akan tertawa!",
  ui_story_5023_50230501_32_dialog_content = "Maafkan aku, wahai pahlawan wanita yang hebat.",
  ui_story_5023_50230501_33_dialog_content = "Saya berharap itu lucu tetapi ini melebihi semua harapan saya. Bagaimana mungkin ada yang tidak menertawakan ini?",
  ui_story_5023_50230501_34_dialog_content = "Kau!",
  ui_story_5023_50230501_35_dialog_content = "Ayolah. Seka wajahmu sampai bersih dengan handuk ini.",
  ui_story_5023_50230501_36_dialog_content = "...",
  ui_story_5023_50230501_37_dialog_content = "Jadi, katakan padaku apa yang terjadi, mengapa kamu tiba-tiba tertarik dengan makeup?",
  ui_story_5023_50230501_38_dialog_content = "... T-Tidak ada alasan!",
  ui_story_5023_50230501_39_dialog_content = "Nah... Anda lihat, Barbara memberitahuku ini akan berfungsi sebagai jimat ajaib yang meningkatkan kekuatan pahlawan wanita!",
  ui_story_5023_50230501_40_dialog_content = "Ya! Tepat sekali!",
  ui_story_5023_50230501_41_dialog_content = "Oh? Kekuatan apa yang sedang kita bicarakan?",
  ui_story_5023_50230501_42_dialog_content = "Err... Jenis apa? um...",
  ui_story_5023_50230501_43_dialog_content = "Yah, itu pasti bukan kecerdasan. Hmm... mungkinkah itu kekuatan karismatik?",
  ui_story_5023_50230501_44_dialog_content = "Bagaimana Anda mengetahuinya? Sial! Absolute Zero Witch bahkan lebih kuat dari yang kukira...",
  ui_story_5023_50230501_45_dialog_content = "Eh… <size=30>Aku ingin jadi dewasa dan glamor sepertimu…</size>",
  ui_story_5023_50230501_46_dialog_content = "Hah? Aku tidak bisa mendengarmu.",
  ui_story_5023_50230501_47_dialog_content = "<size=45>Aku berkata, aku ingin menjadi dewasa dan elegan sepertimu!</size>",
  ui_story_5023_50230501_48_dialog_content = "Karena kamu begitu kuat dan cantik dan kamu selalu menarik perhatian orang tanpa harus melakukan trik apapun...",
  ui_story_5023_50230501_49_dialog_content = "Aww! Tidak pernah berpikir saya akan hidup untuk melihat Anda memuji saya.",
  ui_story_5023_50230501_50_dialog_content = "Itukah sebabnya kamu mencuri pakaian dan topiku?",
  ui_story_5023_50230501_51_dialog_content = "Yeah... Tapi mereka terlalu besar untukku, aku bahkan tidak bisa memakainya...",
  ui_story_5023_50230501_52_dialog_content = "Meski operasi ini gagal, Zeta akan jadi wanita dewasa dan glamor suatu hari nanti! Bahkan lebih baik darimu!",
  ui_story_5023_50230501_53_dialog_content = "Oh, kamu... di sini, duduk di sini.",
  ui_story_5023_50230501_54_dialog_content = "Hah?",
  ui_story_5023_50230501_55_dialog_content = "Wanita tidak dewasa dan elegan karena cara mereka berpakaian.",
  ui_story_5023_50230501_56_dialog_content = "Riasan dan pakaian hanyalah ornamen tingkat permukaan.",
  ui_story_5023_50230501_57_dialog_content = "Tetapi Anda selalu memiliki semua anak laki-laki yang melingkari jari Anda dengan penampilan dan tubuh Anda!",
  ui_story_5023_50230501_58_dialog_content = "Itu... Yah, aku tidak bisa menyangkalnya, tapi sebut saja itu hobiku yang tidak berbahaya.",
  ui_story_5023_50230501_59_dialog_content = "Saya tidak keberatan orang mengomentari sosok saya dengan baik.",
  ui_story_5023_50230501_60_dialog_content = "Tapi saya mendapatkan rasa hormat dengan senjata, mobil, keterampilan tempur, dan otak saya.",
  ui_story_5023_50230501_61_dialog_content = "Perhatian dan pemujaan dari orang lain tidak masalah. Anda harus fokus melakukan apa yang Anda kuasai dan apa yang dapat Anda lakukan.",
  ui_story_5023_50230501_62_dialog_content = "... Astaga, kapan saya juga mulai menceramahi anak-anak ...",
  ui_story_5023_50230501_63_dialog_content = "Zeta mengerti... tapi juga tidak terlalu.",
  ui_story_5023_50230501_64_dialog_content = "Hal-hal apa saja yang dapat saya lakukan?",
  ui_story_5023_50230501_65_dialog_content = "Saya hanya baik untuk melakukan tugas-tugas patroli dasar kecil itu Regina dan yang lain tidak bisa diganggu dengan melakukan ...",
  ui_story_5023_50230501_66_dialog_content = "Jangan meremehkan tugas-tugas kasar yang membantu penduduk desa mengusir Eclipsites.",
  ui_story_5023_50230501_67_dialog_content = "Mereka sangat penting untuk mengembangkan hubungan kita dengan semua desa dan kota di seberang gurun.",
  ui_story_5023_50230501_68_dialog_content = "Saya menangis setiap kali saya membantu Roy potong bawang berry, dan aku bahkan tidak bisa memotongnya dengan baik...",
  ui_story_5023_50230501_69_dialog_content = "Tapi Anda membantunya memastikan semua hidangan terasa enak setiap saat, bukan?",
  ui_story_5023_50230501_70_dialog_content = "Roy punya banyak ide resep di kepalanya, tapi indra perasanya payah. Akan jadi masalah besar kalau tidak ada kau.",
  ui_story_5023_50230501_71_dialog_content = "Sepertinya ada beberapa hal yang bisa saya lakukan dengan cukup baik! Dan saya bisa melakukan lebih baik lagi!",
  ui_story_5023_50230501_72_dialog_content = "Aku tidak tahu kau bisa selembut dan sabar ini...",
  ui_story_5023_50230501_73_dialog_content = "Apakah ada sesuatu yang Anda lupakan?",
  ui_story_5023_50230501_74_dialog_content = "Hah?",
  ui_story_5023_50230501_75_dialog_content = "Ada apa dengan jejak lumpur kecil di jaket putihku ini? Hmm?",
  ui_story_5023_50230501_76_dialog_content = "Anu… Ini…",
  ui_story_5023_50230501_77_dialog_content = "Cuci lagi.",
  ui_story_5023_50230501_78_dialog_content = "T-Tidak masalah! Teman-teman saya sangat pandai mencuci pakaian!",
  ui_story_5023_50230501_79_dialog_content = "Jangan hanya menyebutnya sehari dengan melemparkannya ke mesin Anda dan memutarnya dengan Luminatics Anda.",
  ui_story_5023_50230501_80_dialog_content = "Cuci dengan tangan saja.",
  ui_story_5023_50230501_81_dialog_content = "Benar. Sekarang.",
  ui_story_5023_50230501_82_dialog_content = "*Sniff* Penyihir memang menakutkan...",
  ui_story_5023_50230601_1_dialog_content = "Sungguh malam yang dingin dan gelap gulita...",
  ui_story_5023_50230601_2_dialog_content = "Mungkin karena angin menderu-deru di atas pasir...",
  ui_story_5023_50230601_3_dialog_content = "Atau mungkin memikirkan bahaya tersembunyi yang mengintai di malam hari yang membuatku cemas.",
  ui_story_5023_50230601_4_dialog_content = "Aku membolak-balikkan tubuh dengan gelisah di tempat tidur, insomnia menolak membiarkanku jatuh tertidur.",
  ui_story_5023_50230601_5_dialog_content = "Ide siapa untuk menceritakan kisah-kisah menakutkan di dekat api unggun?",
  ui_story_5023_50230601_6_dialog_content = "Ssst! Dengar!",
  ui_story_5023_50230601_7_dialog_content = "Saat aku melayang bolak-balik antara mimpiku dan dunia nyata, aku mendengar suara.",
  ui_story_5023_50230601_8_dialog_content = "Itu adalah suara seorang wanita, datang tepat dari luar kamarku. Rasanya seperti bisikan di angin ...",
  ui_story_5023_50230601_9_dialog_content = "Namun itu juga terasa seolah-olah tepat di sebelah saya, bernapas ke telinga saya.",
  ui_story_5023_50230601_10_dialog_content = "Hah?",
  ui_story_5023_50230601_11_dialog_content = "Aku duduk sekaligus. Dan apa yang saya lihat di bawah sinar bulan redup ...",
  ui_story_5023_50230601_12_dialog_content = "Berhenti! J-jangan lanjutkan...",
  ui_story_5023_50230601_13_dialog_content = "...dulu Rouge, Bently dan Lompty tidur nyenyak.",
  ui_story_5023_50230601_14_dialog_content = "... Apa-apaan?! Anda menyebutnya— Aduh!",
  ui_story_5023_50230601_15_dialog_content = "Jangan menyela Ruby ketika dia membaca epiknya yang luar biasa, Great Explorer Ruby's Adventures!",
  ui_story_5023_50230601_16_dialog_content = "Adrenalin saya berada di puncaknya.",
  ui_story_5023_50230601_17_dialog_content = "Karena saya tiba-tiba menyadari bahwa meskipun saya berniat menjelajahi seluruh Astra...",
  ui_story_5023_50230601_18_dialog_content = "Aku bahkan belum menjelajahi tempat ini—tanah air kami!",
  ui_story_5023_50230601_19_dialog_content = "Kejadian menyeramkan ini terjadi di Oasis?! SAYA... Fleur, bangun! Bangun!",
  ui_story_5023_50230601_20_dialog_content = "Aaaaaaargh! Kenapa dia tidur seperti orang mati?!",
  ui_story_5023_50230601_21_dialog_content = "Ahem... Aku tidak peduli dengan cerita membosankan seperti ini. Aku belum selesai dengan pelatihan hari ini, jadi aku akan—",
  ui_story_5023_50230601_22_dialog_content = "Tidak meninggalkan di tengah!",
  ui_story_5023_50230601_23_dialog_content = "Jadi saya memutuskan untuk mengikuti hati saya dan naluri penjelajah...",
  ui_story_5023_50230601_24_dialog_content = "Aku segera berangkat untuk melihat apa yang mungkin disembunyikan oleh pangkalan kita yang akrab ini.",
  ui_story_5023_50230601_25_dialog_content = "Ah, aku bahkan tidak tahu kamu mengalami semua itu!",
  ui_story_5023_50230601_26_dialog_content = "Sepertinya mulai sekarang saya perlu membuka satu mata dalam tidur saya untuk memberikan perlindungan yang lebih baik padanya.",
  ui_story_5023_50230601_27_dialog_content = "Saat saya keluar dari pintu, cahaya bulan yang sudah redup menjadi kabur oleh awan gelap, menyelimuti malam dalam kegelapan pekat.",
  ui_story_5023_50230601_28_dialog_content = "Angin, yang menderu-deru sepanjang malam, berhenti. Aku bisa mendengar suara detak jantungku sendiri dalam keheningan yang mematikan.",
  ui_story_5023_50230601_29_dialog_content = "Dug… Dug…",
  ui_story_5023_50230601_30_dialog_content = "Dan kemudian tiba-tiba! Aku mendengarnya lagi!",
  ui_story_5023_50230601_31_dialog_content = "Suara itu menggumamkan sesuatu, tapi hampir tidak bisa disuling...",
  ui_story_5023_50230601_32_dialog_content = "Tunggu, ini salah ketik. Itu seharusnya mengatakan \"nyaris tidak terlihat\" ... Ngomong-ngomong.",
  ui_story_5023_50230601_33_dialog_content = "Itu terlalu jauh dan hampir tidak bisa dilihat, saya tidak bisa mengerti apa yang dikatakannya sama sekali.",
  ui_story_5023_50230601_34_dialog_content = "Tetapi dengan tidak adanya angin, saya dapat mengetahui dari mana suara itu berasal ...",
  ui_story_5023_50230601_35_dialog_content = "Itu tepat di atas saya! Namun...",
  ui_story_5023_50230601_36_dialog_content = "Ruangan di atasku selalu kosong!",
  ui_story_5023_50230601_37_dialog_content = "Ahh!",
  ui_story_5023_50230601_38_dialog_content = "Ciit!",
  ui_story_5023_50230601_39_dialog_content = "Kupikir cerita Ruby adalah favoritmu, jangan jadi pengecut!",
  ui_story_5023_50230601_40_dialog_content = "Itu bukan ceritanya, itu teriakanmu! Itu membuatku takut pada siang hari yang hidup!",
  ui_story_5023_50230601_41_dialog_content = "Dua emosi berbenturan dalam diri saya pada saat itu.",
  ui_story_5023_50230601_42_dialog_content = "Ketakutan akan hal yang tidak diketahui membuatku merinding. Namun aliran adrenalin menyembur ke seluruh tubuh saya seperti listrik, sampai ke otak saya!",
  ui_story_5023_50230601_43_dialog_content = "Namun sensasi menjelajahi hal-hal yang tidak diketahui segera menekan kegelisahan di hati saya dan membantu saya tetap tenang.",
  ui_story_5023_50230601_44_dialog_content = "Saya tidak ragu-ragu dan segera mulai menaiki tangga.",
  ui_story_5023_50230601_45_dialog_content = "Ruby! Tolong bangunkan aku jika ini terjadi lagi!",
  ui_story_5023_50230601_46_dialog_content = "Hal semacam ini terlalu berbahaya untuk kau hadapi sendiri!",
  ui_story_5023_50230601_47_dialog_content = "Aku berhenti di luar kamar kosong itu untuk waktu yang lama.",
  ui_story_5023_50230601_48_dialog_content = "Pintu yang biasanya terkunci terbuka sedikit, tetapi tidak ada cahaya di dalamnya.",
  ui_story_5023_50230601_49_dialog_content = "Di biara yang gelap... ehem.",
  ui_story_5023_50230601_50_dialog_content = "Di jurang yang gelap, rasanya seperti ada sesuatu yang mengawasiku.",
  ui_story_5023_50230601_51_dialog_content = "Untuk sesaat, aku hanya ingin berbalik dan lari. Namun, tiba-tiba aku teringat pada Jim.",
  ui_story_5023_50230601_52_dialog_content = "Idola saya, Pak Jim sang penjelajah legendaris, pasti akan mengatasi rasa takutnya dan memasuki ruangan gelap untuk sebuah jawaban!",
  ui_story_5023_50230601_53_dialog_content = "Maka, aliran keberanian yang hangat memenuhi hati saya dan menghilangkan rasa takut saya.",
  ui_story_5023_50230601_54_dialog_content = "Saya meletakkan satu tangan di pegangan, dan tepat ketika saya akan masuk, saya mendengar suara itu lagi.",
  ui_story_5023_50230601_55_dialog_content = "Kali ini, itu keras dan jelas—",
  ui_story_5023_50230601_56_dialog_content = "\"Terima kasih atas kebersamaanmu selama ini. Tapi terkadang aku masih merasa sangat kesepian...\"",
  ui_story_5023_50230601_57_dialog_content = "\"Ada hal-hal yang harus kulakukan.\"",
  ui_story_5023_50230601_58_dialog_content = "A...Apa maksudnya?",
  ui_story_5023_50230601_59_dialog_content = "Aku hendak mendekat ketika aku mendengar suara pistol sedang dimuat.",
  ui_story_5023_50230601_60_dialog_content = "Saya merasakan keinginan yang menusuk tulang untuk membunuh. Itu menembus kegelapan serta tubuhku seperti belati tajam.",
  ui_story_5023_50230601_61_dialog_content = "Aku mundur selangkah demi selangkah. Sejujurnya, saya tidak ingat bagaimana saya kembali ke tempat tidur.",
  ui_story_5023_50230601_62_dialog_content = "Keesokan paginya, aku bergegas ke kamar di lantai atas…",
  ui_story_5023_50230601_63_dialog_content = "Kamar itu kosong.",
  ui_story_5023_50230601_64_dialog_content = "Masih banyak hal yang tidak diketahui di dunia ini yang menunggu untuk ditemukan...",
  ui_story_5023_50230601_65_dialog_content = "Itu pasti hantu! Aku yakin!",
  ui_story_5023_50230601_66_dialog_content = "Jika Anda tinggal di sana lebih lama lagi, suara itu akan menyeret Anda ke dunia hantu!",
  ui_story_5023_50230601_67_dialog_content = "Dunia hantu? Benarkah itu, Ruby?",
  ui_story_5023_50230601_68_dialog_content = "Maaf, tapi tebakanmu sama bagusnya dengan tebakanku.",
  ui_story_5023_50230601_69_dialog_content = "Petualanganku gagal. Kebenarannya tetap tersembunyi dalam pekatnya kabut.",
  ui_story_5023_50230601_70_dialog_content = "Saya masih memiliki banyak ruang untuk tumbuh dan berkembang sebagai seorang penjelajah...",
  ui_story_5023_50230601_71_dialog_content = "Jika ada dunia hantu, itu akan menarik. Tidakkah kalian berpikir?",
  ui_story_5023_50230601_72_dialog_content = "Ya! Aku akan berada di sisi Ruby apapun yang terjadi!",
  ui_story_5023_50230601_73_dialog_content = "Kriek!",
  ui_story_5023_50230601_74_dialog_content = "Bisa kah saya pergi sekarang...",
  ui_story_5023_50230601_75_dialog_content = "Hatsyiii!",
  ui_story_5023_50230601_76_dialog_content = "Kau baik-baik saja? Perlu jaket?",
  ui_story_5023_50230601_77_dialog_content = "Aku tidak kedinginan. Itu hanya bersin acak ...",
  ui_story_5023_50230601_78_dialog_content = "Saya akan mengatakan itu karena seseorang menggosipkan saya, tetapi Anda berbicara tentang saya di depan saya, bukan di belakang saya ... jadi itu pasti debu.",
  ui_story_5023_50230601_79_dialog_content = "Apakah Anda yakin tidak ingin istirahat beberapa hari sebelum berangkat lagi?",
  ui_story_5023_50230601_80_dialog_content = "Aku sudah menjaga kamarmu tak tersentuh.",
  ui_story_5023_50230601_81_dialog_content = "Tidak dibutuhkan. Saya mendapat pesan dari kontak melalui Courier Union mengenai sekumpulan barang yang saya cari.",
  ui_story_5023_50230601_82_dialog_content = "Baik-baik saja maka. Beri tahu saya jika Anda membutuhkan cadangan.",
  ui_story_5023_50230601_83_dialog_content = "Azure, jaga dirimu. Eye of the Lynx, jaga dia.",
  ui_story_5023_50230601_84_dialog_content = "… Kenapa kau berbicara pada senapanku?",
  ui_story_5023_50230601_85_dialog_content = "Hmm? Apakah Anda tidak sering berbicara dengannya ketika Anda sendirian?",
  ui_story_5023_50230601_86_dialog_content = "Aku pergi. Saya merasa ini akan menjadi perjalanan yang sangat bermanfaat.",
  ui_story_5023_50230601_87_dialog_content = "Itu akan sempurna mengingat berapa banyak uang yang selalu kita butuhkan untuk perbaikan setelah Blazing Rally...",
  ui_story_5023_50230601_88_dialog_content = "Selamat berburu."
}
return config
